choose.when:
SELECT h.household_no householdNo,h.address,h.region_code regionCode,h.status FROM household h WHERE 1=1 AND h.region_code=#{filters.regionCode}
AND 1=0
AND 1=0 AND EXISTS(SELECT 1 FROM business_application a WHERE a.target_household_id=h.household_id AND a.applicant_department_id=#{scope.departmentId}) AND h.region_code IN #{regionCodeItem} AND 1=0

SELECT a.application_no applicationNo,a.business_type businessType,a.status,a.applicant_region_code regionCode,a.created_at createdAt
FROM business_application a WHERE a.business_type IN('MIGRATION_IN','MIGRATION_OUT')

  AND 1=0

  AND a.applicant_user_id=#{scope.userId}
  AND a.applicant_department_id=#{scope.departmentId}
  AND a.applicant_region_code IN #{regionCodeItem}
  AND 1=0
